package com.sloth.client.screen;
import com.sloth.client.module.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class AccessibilityStudioScreen extends SlothScreen {
 private final Screen parent;private int x,y,w,h;public AccessibilityStudioScreen(Screen p){super(Component.literal("Accessibility Studio"));parent=p;}
 protected void init(){w=Math.min(440,width-24);h=Math.min(270,height-20);x=(width-w)/2;y=(height-h)/2;String[] presets={"Larger HUD text","High contrast HUDs","Reduced menu motion","Extra large HUD text"};for(int i=0;i<4;i++){final int n=i;button(x+14,y+54+i*30,w-28,24,"Preview "+presets[i],b->{var t=ModuleManager.snapshot();var modules=t.getAsJsonObject("modules");for(HudModule hud:ModuleManager.hudModules()){var s=modules.getAsJsonObject(hud.id).getAsJsonObject("settings");if(n==0||n==3)s.addProperty("scale",n==3?1.5:1.3);if(n==1){s.addProperty("background",true);s.addProperty("shadow",false);for(String k:new String[]{"text_color","background_color","border_color"}){var c=new com.google.gson.JsonObject();c.addProperty("argb",k.equals("background_color")?"#FF14141A":"#FFFFFFFF");c.addProperty("chroma",false);s.add(k,c);}}}if(n==2){modules.getAsJsonObject("menu_theme").getAsJsonObject("settings").addProperty("animations",false);var s=modules.getAsJsonObject("main_menu").getAsJsonObject("settings");s.addProperty("particles",false);s.addProperty("parallax",false);}minecraft.setScreen(new SetupReviewScreen(this,presets[n],t));});}button(x+w-104,y+h-32,90,20,"Back",b->onClose());}
 public void renderBackground(GuiGraphics g,int mx,int my,float t){super.renderBackground(g,mx,my,t);Ui.panel(g,x,y,w,h,Ui.BG);}public void render(GuiGraphics g,int mx,int my,float t){super.render(g,mx,my,t);g.drawString(font,"ACCESSIBILITY STUDIO",x+14,y+14,Ui.TEXT,false);g.drawString(font,"Review individual changes before applying. Undo is available.",x+14,y+32,Ui.MUTED,false);}public void onClose(){minecraft.setScreen(parent);}
}
